// ===============================================================================
// DAEMIND SRE - GERADOR DE COPY DE ESCASSEZ BASEADO EM ESTOQUE FÍSICO REAL
// ===============================================================================
const items = $input.all();
if (!items || items.length === 0 || !items[0].json?.pedido_id) {
  return [];
}

return items.map(item => {
  const j = item.json;
  const saldo = parseInt(j.saldo_estoque || 10, 10);
  let escassezTexto = '';

  if (saldo <= 3) {
    escassezTexto = `🚨 *Atenção:* Restam apenas *${saldo} unidades* do item *${j.produto_nome || 'seu produto'}* em nosso estoque físico!`;
  } else if (saldo <= 8) {
    escassezTexto = `⚡ O item *${j.produto_nome || 'seu produto'}* está com alta procura e poucas unidades restantes.`;
  } else {
    escassezTexto = `⏳ A sua reserva de estoque expira em breve.`;
  }

  const msg = `Olá, *${j.cliente_nome}*! Tudo bem?\n\nPassando para avisar sobre o seu pedido *#${j.numero_pedido}* de *R$ ${parseFloat(j.valor_total).toFixed(2)}*.\n\n${escassezTexto}\n\nPara garantir que o seu pacote seja separado hoje mesmo, conclua o pagamento do seu PIX/Boleto.\n\nSe precisar de ajuda com a 2ª via ou tiver qualquer dúvida, responda a esta mensagem! 🛍️`;

  return {
    json: {
      ...j,
      mensagem_whatsapp: msg,
      idempotency_key: `urgencia_ped_${j.pedido_id}_${j.numero_pedido}`
    }
  };
});
